package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsIgnoreCase_TriageGen0Test {

    @Test
    public void testContainsIgnoreCase_NullStr() {
        assertFalse("Should return false when str is null", 
            StringUtils.containsIgnoreCase(null, "abc"));
    }

    @Test
    public void testContainsIgnoreCase_NullSearchStr() {
        assertFalse("Should return false when searchStr is null", 
            StringUtils.containsIgnoreCase("abc", null));
    }

    @Test
    public void testContainsIgnoreCase_BothNull() {
        assertFalse("Should return false when both are null", 
            StringUtils.containsIgnoreCase(null, null));
    }

    @Test
    public void testContainsIgnoreCase_ExactMatch() {
        assertTrue("Should return true for exact match", 
            StringUtils.containsIgnoreCase("abc", "abc"));
    }

    @Test
    public void testContainsIgnoreCase_CaseInsensitiveMatch() {
        assertTrue("Should return true for case-insensitive match", 
            StringUtils.containsIgnoreCase("HelloWorld", "hello"));
        assertTrue("Should return true for case-insensitive match reversed", 
            StringUtils.containsIgnoreCase("hello", "HELLO"));
        assertTrue("Should return true for mixed case match", 
            StringUtils.containsIgnoreCase("aBcDeF", "BcD"));
    }

    @Test
    public void testContainsIgnoreCase_NoMatch() {
        assertFalse("Should return false when searchStr is not in str", 
            StringUtils.containsIgnoreCase("abcdef", "xyz"));
    }

    @Test
    public void testContainsIgnoreCase_EmptySearchStr() {
        // Based on the logic: contains(str.toUpperCase(), "".toUpperCase())
        // StringUtils.contains usually returns true for empty search strings
        assertTrue("Should return true when searchStr is empty", 
            StringUtils.containsIgnoreCase("abc", ""));
    }

    @Test
    public void testContainsIgnoreCase_EmptyStr() {
        assertFalse("Should return false when str is empty and searchStr is not", 
            StringUtils.containsIgnoreCase("", "a"));
    }

    @Test
    public void testContainsIgnoreCase_BothEmpty() {
        assertTrue("Should return true when both are empty", 
            StringUtils.containsIgnoreCase("", ""));
    }

    @Test
    public void testContainsIgnoreCase_SpecialCharacters() {
        assertTrue("Should handle special characters case-insensitively", 
            StringUtils.containsIgnoreCase("!@#$%", "!@#"));
        assertFalse("Should return false for non-matching special characters", 
            StringUtils.containsIgnoreCase("!@#$%", "^&*"));
    }
}
